```ts
export interface DeduperOptions {
  ttlMs: number;
  pruneEvery?: number;
  now?: () => number;
}

export class MessageDeduper {
  private readonly seen = new Map<string, number>();
  private readonly ttlMs: number;
  private readonly pruneEvery: number;
  private readonly now: () => number;
  private operations = 0;

  constructor(options: DeduperOptions) {
    if (!Number.isFinite(options.ttlMs) || options.ttlMs <= 0) {
      throw new RangeError("ttlMs must be positive");
    }
    if (!Number.isInteger(options.pruneEvery ?? 256) || (options.pruneEvery ?? 256) <= 0) {
      throw new RangeError("pruneEvery must be a positive integer");
    }
    this.ttlMs = options.ttlMs;
    this.pruneEvery = options.pruneEvery ?? 256;
    this.now = options.now ?? (() => Date.now());
  }

  isDuplicate(platform: string, messageId?: string | null): boolean {
    const normalizedPlatform = platform.trim();
    const normalizedId = messageId?.trim();
    if (!normalizedPlatform || !normalizedId) return false;

    const current = this.now();
    this.operations += 1;
    if (this.operations % this.pruneEvery === 0) this.prune(current);

    const key = JSON.stringify([normalizedPlatform, normalizedId]);
    const expiresAt = this.seen.get(key);
    if (expiresAt !== undefined && expiresAt > current) return true;

    this.seen.set(key, current + this.ttlMs);
    return false;
  }

  prune(current = this.now()): void {
    for (const [key, expiresAt] of this.seen) {
      if (expiresAt <= current) this.seen.delete(key);
    }
  }
}
```

核心可以这样写，生产环境再按吞吐量把过期清理改成周期任务。

```ts
type Outcome = "processed" | "joined" | "duplicate";

export class MessageGate {
  private readonly inFlight = new Map<string, Promise<void>>();
  private readonly completed = new Map<string, number>();

  constructor(
    private readonly ttlMs: number,
    private readonly now: () => number = Date.now,
  ) {}

  async run(
    platform: string,
    messageId: string | undefined,
    task: () => Promise<void>,
  ): Promise<Outcome> {
    const p = platform.trim();
    const id = messageId?.trim();
    if (!p || !id) {
      await task();
      return "processed";
    }

    const key = JSON.stringify([p, id]);
    const current = this.now();
    const expiresAt = this.completed.get(key);
    if (expiresAt !== undefined && expiresAt > current) return "duplicate";
    if (expiresAt !== undefined) this.completed.delete(key);

    const existing = this.inFlight.get(key);
    if (existing) {
      await existing;
      return "joined";
    }

    const running = (async () => {
      await task();
      this.completed.set(key, this.now() + this.ttlMs);
    })();
    this.inFlight.set(key, running);
    try {
      await running;
      return "processed";
    } finally {
      if (this.inFlight.get(key) === running) this.inFlight.delete(key);
    }
  }
}
```

好，边界一并收紧：每行按字节限长，支持 CRLF、空行和无换行尾行，非法 UTF-8 或 JSON 都会明确抛出。

```python
from __future__ import annotations

import json
from typing import Any


class JsonlStreamParser:
    def __init__(self, max_line_bytes: int = 1_048_576) -> None:
        if max_line_bytes <= 0:
            raise ValueError("max_line_bytes must be positive")
        self._max_line_bytes = max_line_bytes
        self._buffer = bytearray()
        self._line_number = 0
        self._closed = False

    def feed(self, chunk: bytes) -> list[Any]:
        if self._closed:
            raise RuntimeError("parser is already finalized")
        if not isinstance(chunk, bytes):
            raise TypeError("chunk must be bytes")

        values: list[Any] = []
        start = 0
        while True:
            newline = chunk.find(b"\n", start)
            if newline < 0:
                self._append(chunk[start:])
                break
            self._append(chunk[start:newline])
            value = self._finish_line()
            if value is not None:
                values.append(value)
            start = newline + 1
        return values

    def finalize(self) -> list[Any]:
        if self._closed:
            raise RuntimeError("parser is already finalized")
        self._closed = True
        if not self._buffer:
            return []
        value = self._finish_line()
        return [] if value is None else [value]

    def _append(self, part: bytes) -> None:
        if len(self._buffer) + len(part) > self._max_line_bytes:
            raise ValueError("JSONL line exceeds max_line_bytes")
        self._buffer.extend(part)

    def _finish_line(self) -> Any | None:
        self._line_number += 1
        raw = bytes(self._buffer)
        self._buffer.clear()
        if raw.endswith(b"\r"):
            raw = raw[:-1]
        if not raw.strip():
            return None
        try:
            return json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ValueError(f"invalid JSONL at line {self._line_number}") from exc
```

下面按分钟粒度实现。调用方必须传入带时区的 `after_utc`，并确保运行环境安装了 IANA 时区数据；数据库里保存时区名和本地钟点，最终执行时刻才保存或比较 UTC。

```python
from __future__ import annotations

from datetime import datetime, time, timedelta, timezone
from zoneinfo import ZoneInfo


def _valid_utc_instants(local_naive: datetime, zone: ZoneInfo) -> list[datetime]:
    instants: set[datetime] = set()
    for fold in (0, 1):
        local = local_naive.replace(tzinfo=zone, fold=fold)
        utc = local.astimezone(timezone.utc)
        round_trip = utc.astimezone(zone).replace(tzinfo=None)
        if round_trip == local_naive:
            instants.add(utc)
    return sorted(instants)


def _resolve_first_valid(local_naive: datetime, zone: ZoneInfo) -> datetime:
    for minutes in range(24 * 60 + 1):
        instants = _valid_utc_instants(
            local_naive + timedelta(minutes=minutes), zone
        )
        if instants:
            return instants[0]
    raise ValueError("no valid local time found within 24 hours")


def next_daily_run(
    after_utc: datetime, local_time: time, time_zone: str
) -> datetime:
    if after_utc.tzinfo is None or after_utc.utcoffset() is None:
        raise ValueError("after_utc must be timezone-aware")
    if local_time.tzinfo is not None:
        raise ValueError("local_time must not carry tzinfo")
    if local_time.second or local_time.microsecond:
        raise ValueError("local_time must have minute precision")

    after = after_utc.astimezone(timezone.utc)
    zone = ZoneInfo(time_zone)
    start_date = after.astimezone(zone).date()

    for day_offset in range(370):
        local_naive = datetime.combine(
            start_date + timedelta(days=day_offset), local_time
        )
        candidate = _resolve_first_valid(local_naive, zone)
        if candidate > after:
            return candidate
    raise RuntimeError("could not find the next daily run")
```

