可以让两个执行者共享一个递增索引，每个结果仍写回原位置：

```js
const assert = require('node:assert/strict');

async function mapWithLimit(items, limit, worker) {
  if (!Number.isInteger(limit) || limit < 1) throw new RangeError('limit must be a positive integer');
  const results = new Array(items.length);
  let nextIndex = 0;
  async function runner() {
    while (true) {
      const index = nextIndex++;
      if (index >= items.length) return;
      results[index] = await worker(items[index], index);
    }
  }
  const runnerCount = Math.min(limit, items.length);
  await Promise.all(Array.from({ length: runnerCount }, () => runner()));
  return results;
}

async function test() {
  let active = 0;
  let maxActive = 0;
  const delays = [30, 5, 20, 1];
  const results = await mapWithLimit(delays, 2, async (ms, index) => {
    active += 1;
    maxActive = Math.max(maxActive, active);
    await new Promise(resolve => setTimeout(resolve, ms));
    active -= 1;
    return `task-${index}`;
  });
  assert.equal(maxActive, 2);
  assert.deepEqual(results, ['task-0', 'task-1', 'task-2', 'task-3']);
  assert.deepEqual(await mapWithLimit([], 2, async value => value), []);
  await assert.rejects(() => mapWithLimit([1], 0, async value => value), /positive integer/);
  console.log('bounded parallel test passed');
}

test().catch(error => { console.error(error); process.exitCode = 1; });
```

