import unittest


def compact_ranges(numbers):
    items = list(numbers)
    if any(type(value) is not int for value in items):
        raise TypeError("numbers must contain only integers")

    values = sorted(set(items))
    if not values:
        return []

    result = []
    start = previous = values[0]
    for value in values[1:]:
        if value != previous + 1:
            result.append((start, previous))
            start = value
        previous = value

    result.append((start, previous))
    return result


class CompactRangesTests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(compact_ranges([]), [])

    def test_unsorted_duplicates(self):
        self.assertEqual(
            compact_ranges([5, 2, 3, 3, 4, 9]),
            [(2, 5), (9, 9)],
        )

    def test_negative_numbers(self):
        self.assertEqual(
            compact_ranges([-1, -3, -2, 2]),
            [(-3, -1), (2, 2)],
        )

    def test_generator(self):
        self.assertEqual(
            compact_ranges(value for value in [8, 6, 7]),
            [(6, 8)],
        )

    def test_invalid_types(self):
        for value in (True, 1.5, "2"):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    compact_ranges([1, value, 3])


if __name__ == "__main__":
    unittest.main()
