def group_tasks(statuses, tasks):
    status_list = list(statuses)
    if any(type(status) is not str or not status for status in status_list):
        raise TypeError("statuses must contain non-empty strings")
    if len(set(status_list)) != len(status_list):
        raise ValueError("statuses must not contain duplicates")

    groups = {status: [] for status in status_list}
    for title, status in tasks:
        if status not in groups:
            raise ValueError(f"unknown status: {status}")
        groups[status].append(title)
    return groups


class GroupTasksTests(unittest.TestCase):
