```python
import re
import unittest

_DURATION_RE = re.compile(r"\s*(?:(\d+)\s*[hH])?\s*(?:(\d+)\s*[mM])?\s*(?:(\d+)\s*[sS])?\s*")

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("duration must be a string")
    match = _DURATION_RE.fullmatch(text)
    if match is None or all(group is None for group in match.groups()):
        raise ValueError("invalid duration")
    hours, minutes, seconds = (int(group or 0) for group in match.groups())
    if minutes >= 60 or seconds >= 60:
        raise ValueError("minutes and seconds must be less than 60")
    return hours * 3600 + minutes * 60 + seconds

class ParseDurationTests(unittest.TestCase):
    def test_compact_values(self):
        self.assertEqual(parse_duration("1h30m"), 5400); self.assertEqual(parse_duration("45s"), 45)
    def test_spaces_and_uppercase(self): self.assertEqual(parse_duration(" 2 H 5 M 9 S "), 7509)
    def test_zero_is_valid(self): self.assertEqual(parse_duration("0s"), 0)
    def test_rejects_empty_and_malformed_values(self):
        for value in ("", "   ", "30m1h", "1h20m5m", "1.5h", "-2m", "20"):
            with self.subTest(value=value):
                with self.assertRaises(ValueError): parse_duration(value)
    def test_rejects_out_of_range_components(self):
        for value in ("1h60m", "1m60s"):
            with self.subTest(value=value):
                with self.assertRaises(ValueError): parse_duration(value)
    def test_rejects_non_string(self):
        with self.assertRaises(TypeError): parse_duration(90)

if __name__ == "__main__":
    unittest.main()
```

这六项测试已使用 Python 标准库实际运行通过。

我把分页接口返回的记录按 id 建索引，结果第一条总会消失。最小复现是：

```python
def index_items(pages):
    by_id = {}
    for page in pages:
        for item in page:
            if item.get("id"):
                by_id[item["id"]] = item
    return by_id

pages = [[{"id": 0, "name": "root"}, {"id": 1, "name": "alice"}]]
print(index_items(pages))
```

输出里只有 id 1。

可以，把缺失、空值和重复分开处理：

```python
def index_items(pages):
    by_id = {}
    for page in pages:
        for item in page:
            if "id" not in item:
                raise ValueError("item missing id")
            item_id = item["id"]
            if item_id is None:
                raise ValueError("item id must not be null")
            if item_id in by_id:
                raise ValueError(f"duplicate id: {item_id!r}")
            by_id[item_id] = item
    return by_id
```

这里不依赖 id 的真值，也没有把非法的 `None` 当成普通键；分页顺序不再悄悄决定结果。

用标准库 `unittest` 覆盖原始故障和三个契约分支：

```python
import unittest


class TestIndexItems(unittest.TestCase):
    def test_preserves_zero_id(self):
        result = index_items([[{"id": 0, "name": "root"}]])
        self.assertEqual(result[0]["name"], "root")

    def test_rejects_missing_id(self):
        with self.assertRaisesRegex(ValueError, "missing id"):
            index_items([[{"name": "unknown"}]])

    def test_rejects_null_id(self):
        with self.assertRaisesRegex(ValueError, "must not be null"):
            index_items([[{"id": None}]])

    def test_rejects_duplicate_across_pages(self):
        with self.assertRaisesRegex(ValueError, "duplicate id: 2"):
            index_items([[{"id": 2}], [{"id": 2}]])


if __name__ == "__main__":
    unittest.main()
```

这四项测试可直接运行，分别验证 `0` 未被误丢，并让缺失、空值和跨页重复明确失败。
